SELECT be.id, be.status, be.receipt_id, be.donor_id, be.agent_name, be.payer_name, be.amount, r.donor_id as r_donor, r.log_id as r_log, r.agent_name as r_agent FROM bank_audit_entries be LEFT JOIN receipts r ON r.id = be.receipt_id WHERE be.status != 'verified' AND be.receipt_id IS NOT NULL AND (be.agent_name IS NULL OR be.agent_name = '' OR be.agent_name ILIKE '%suspense%') ORDER BY be.id DESC LIMIT 20;
